#!/usr/bin/env node
// PreToolUse hook (Claude Code) for Armory's hard rule 1: never hand-edit catalog.json. It is generated by
// `pnpm catalog` (ingest/catalog.mjs) from brain/, the source of truth. Edits and writes to the root
// catalog.json are denied with the reason; everything else passes. Reads the hook payload on stdin.
import { readFileSync } from "node:fs";
import { relative, resolve } from "node:path";

let payload = {};
try {
  payload = JSON.parse(readFileSync(0, "utf8") || "{}");
} catch {
  // Intentionally silent: an unreadable payload must not block the session.
}
const file = payload?.tool_input?.file_path || payload?.tool_input?.path || "";
const root = process.env.CLAUDE_PROJECT_DIR || process.cwd();
const rel = file ? relative(root, resolve(root, file)) : "";
if (rel === "catalog.json" || rel === "catalog.json.gz") {
  console.log(JSON.stringify({
    hookSpecificOutput: {
      hookEventName: "PreToolUse",
      permissionDecision: "deny",
      permissionDecisionReason:
        "catalog.json is generated, never hand-edited (AGENTS.md hard rule 1). Edit the component's page in brain/components/, then run `pnpm catalog` and `pnpm validate`.",
    },
  }));
}
process.exit(0);
